"""Make the ~14 s vertical trailer (1080x1920 MP4) for one issue.
Usage: python3 tools/trailer.py N [out.mp4] [--promo PATH]
--promo plays a clip (e.g. from tools/site_promo.py) before the issue trailer.
Needs playwright (pre-installed) and ffmpeg."""
import os, sys, subprocess, shutil, tempfile
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PROMO=None
if '--promo' in sys.argv:
    i=sys.argv.index('--promo'); PROMO=os.path.abspath(sys.argv[i+1]); del sys.argv[i:i+2]
JSCODE='const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];\nconst page=$(\'.page\'),logo=$(\'.m2 .lg\'),title=$(\'.m2 .box\'),il=$(\'.m2 .il\'),stamp=$(\'.stamp\'),brk=$(\'.brk\'),h=$(\'.brk h3\'),end=$(\'#endc\'),dc=$(\'#dcard\'),dl=$(\'#dcard .lb\'),D=dc?4.4:0,nc=$(\'#ncard\'),N=nc?4.6:0,nis=$$(\'#ncard li\'),nl=$(\'#ncard .lb\');\nconst ic=$(\'#icard\'),S=ic?2.6:0,ils=$$(\'#icard .ln\');\nconst H=h.textContent, IL=il.textContent;\nconst rows=$$(\'.row\');\nconst cl=(x)=>Math.max(0,Math.min(1,x)), seg=(t,a,b)=>cl((t-a)/(b-a));\nconst eo=x=>1-Math.pow(1-x,3), back=x=>{const c=1.7;return 1+(c+1)*Math.pow(x-1,3)+c*Math.pow(x-1,2)};\n// "Read more": keep the dropdown open but squeeze its text, then show a tap and let it grow\nconst mores=$$(\'.page details.more\').map(d=>{d.open=true;const w=document.createElement(\'div\');w.className=\'mwrap\';[...d.children].filter(c=>c.tagName!==\'SUMMARY\').forEach(c=>w.appendChild(c));d.appendChild(w);const ring=document.createElement(\'i\');ring.className=\'tapr\';d.querySelector(\'summary\').appendChild(ring);return {d,w,ring,full:w.scrollHeight}});\nconst news=$$(\'.page .disc, .page details.more summary\').map(el=>{const b=document.createElement(\'b\');b.className=\'newb\';b.textContent=\'NEW\';el.appendChild(b);return b});\nconst rest=$$(\'.page > .sec, .page > .story, .page > .score, .page > .foot, .page > .chat, .page > .sig, .page > .burn\').concat($$(\'.page > .brk\').slice(1));\nbrk.style.minHeight=brk.offsetHeight+\'px\';\nconst X=mores.length?2.5:1.5; // extra scroll time for a longer issue\nconst maxScroll=page.offsetHeight-853+36;\nmores.forEach(m=>m.w.style.maxHeight=\'0px\');\nconst spAt=t=>{let sp=seg(t,5.6,11.6);return sp<.5?2*sp*sp:1-Math.pow(-2*sp+2,2)/2};\nconst yAt=(el,t)=>{const r=el.getBoundingClientRect(),pr=page.getBoundingClientRect();return (r.top-pr.top)+18-spAt(t)*maxScroll};\nconst when=(el,frac)=>{for(let t=5.6;t<11.6;t+=0.02){if(yAt(el,t)<853*frac)return t}return 11.6};\nmores.forEach(m=>{m.tap=when(m.d.querySelector(\'summary\'),0.62)});\nconst newT=news.map(b=>when(b.parentNode,0.8));\n// time warp: freeze after the issue line for the intro card, and slow the scroll down\nfunction warp(T){if(T<2.3)return T;if(T<2.3+S)return 2.3;T-=S;if(T<5.6)return T;if(T<11.6+X)return 5.6+(T-5.6)*6/(6+X);return T-X}\nwindow.setT=function(T){\n  const t=warp(T);\n  let a=eo(seg(t,0.1,0.6)); logo.style.opacity=a; logo.style.transform=`translateY(${(1-a)*20}px)`;\n  a=eo(seg(t,0.4,1.0)); title.style.opacity=a; title.style.transform=`translateY(${(1-a)*24}px)`;\n  let p=seg(t,1.2,1.5); stamp.style.opacity=p>0?1:0;\n  let sc=p<1?2.6-1.6*eo(p):1; let shake=(t>1.5&&t<1.75)?Math.sin(t*90)*3*(1.75-t)*4:0;\n  stamp.style.transform=`rotate(-9deg) scale(${sc}) translateX(${shake}px)`;\n  let n=Math.floor(IL.length*seg(t,1.7,2.3)); il.textContent=IL.slice(0,n)||\' \';\n  if(ic){const k=seg(T,2.35,2.6),o=1-seg(T,2.3+S-0.35,2.3+S);ic.style.opacity=Math.min(eo(k),o);ic.style.transform=`scale(${k<1?1.25-0.25*eo(k):1})`;\n    ils.forEach((l,i)=>{const q=seg(T,2.55+i*0.45,2.85+i*0.45);l.style.opacity=cl(q*2);l.style.transform=`scale(${q<1?2.2-1.2*eo(q):1}) rotate(${i%2?2:-2}deg)`})}\n  a=eo(seg(t,2.4,2.9)); brk.style.opacity=a; brk.style.transform=`translateX(${(1-a)*-40}px)`;\n  n=Math.floor(H.length*seg(t,2.8,4.4)); h.textContent=H.slice(0,n)+(t>2.8&&t<4.6&&Math.floor(t*4)%2?\'▍\':\'\');\n  $$(\'.brk .dek,.brk .bl\').forEach(e=>e.style.opacity=eo(seg(t,4.4,4.9)));\n  page.style.transform=`translateY(${-spAt(t)*maxScroll}px)`;\n  mores.forEach(m=>{const r=seg(t,m.tap,m.tap+0.35);m.ring.style.opacity=r>0&&r<1?1-r:0;m.ring.style.transform=`translate(-50%,-50%) scale(${0.3+1.6*r})`;\n    const g=eo(seg(t,m.tap+0.2,m.tap+0.9));m.w.style.maxHeight=(g*m.full)+\'px\';m.d.classList.toggle(\'tapped\',t>m.tap+0.15)});\n  news.forEach((b,i)=>{const q=seg(t,newT[i],newT[i]+0.3);b.style.opacity=q>0?1:0;b.style.transform=`rotate(8deg) scale(${q<1?2.4-1.4*eo(q):1})`});\n  rows.forEach((r,i)=>{const q=back(seg(t,10.6+i*0.35,10.95+i*0.35));const ck=r.querySelector(\'.ck\');ck.style.transform=`scale(${q})`;r.style.opacity=0.25+0.75*cl(seg(t,10.5+i*0.35,10.8+i*0.35))});\n  rest.forEach(e=>e.style.opacity=eo(seg(t,4.8,5.5)));\n  if(nc){nc.style.opacity=eo(seg(t,12.2,12.5));let q0=seg(t,12.4,12.7);nl.style.opacity=q0>0?1:0;nl.style.transform=`rotate(-4deg) scale(${q0<1?2.6-1.6*eo(q0):1})`;nis.forEach((li,i)=>{const q=seg(t,12.8+i*0.42,13.15+i*0.42);li.style.opacity=cl(q*2);li.style.transform=`translateX(${(1-eo(q))*-60}px) scale(${0.9+0.1*back(q)})`})}\n  if(dc){dc.style.opacity=eo(seg(t,12.2+N,12.6+N));let q=seg(t,12.6+N,12.9+N);dl.style.opacity=q>0?1:0;dl.style.transform=`rotate(-4deg) scale(${q<1?2.6-1.6*eo(q):1})`;}\n  end.style.opacity=eo(seg(t,12.2+N+D,12.8+N+D));\n};\nwindow.EXTRA=S+X;\nsetT(0);\n'
n=sys.argv[1]; out=sys.argv[2] if len(sys.argv)>2 else f'/home/claude/off-the-record-issue-{n}-trailer.mp4'
s=open(os.path.join(ROOT,'src',f'issue{n}.html')).read()
has_more='<details class="more"' in s
s=s.replace('body{margin:0;background:#eceef2;padding:18px;width:480px;','body{margin:0;background:#eceef2;padding:0;width:480px;height:853px;overflow:hidden;')
s=s.replace('</style>','#stage{'+'position:relative;width:480px;height:853px;overflow:hidden;padding:18px}\n#endc{position:absolute;inset:0;background:#141416;color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;opacity:0;text-align:center}\n#endc .t{font-family:PF;font-weight:900;font-size:44px;letter-spacing:-1px}\n#endc .s{font-family:MONO;font-weight:700;font-size:13px;letter-spacing:2px;color:#ff5a70;margin-top:14px}\n#endc .c{font-size:17px;font-weight:700;margin-top:26px;color:#e8e8ec}\n'+'</style>',1)
s=s.replace('<body><div class="page">','<body><div id="stage"><div class="page">',1)
END=f"""</div>
<div id="endc"><svg width="64" height="64" viewBox="0 0 100 100"><rect x="4" y="4" width="92" height="92" rx="20" fill="#fff" stroke="#fff" stroke-width="4"/><rect x="16" y="22" width="56" height="13" rx="1.5" fill="#111"/><rect x="16" y="41" width="68" height="18" rx="1.5" fill="#e5384f"/><text x="22" y="55" font-family="MONO" font-weight="700" font-size="14" fill="#fff" letter-spacing="2">OTR</text><rect x="16" y="65" width="46" height="13" rx="1.5" fill="#111"/></svg><div class="t">Off the Record</div><div class="s">ISSUE NO. {n} · OUT NOW</div><div class="c">Read it at<br>camrenmulcair.github.io/off-the-record</div></div>
</div>
<script>"""+JSCODE+"""</script></body></html>"""
import re
m=re.search(r'<div class="disc">\s*<span class="lb">[^<]*</span>\s*<p>(.*?)</p>\s*</div>',s,re.S)
nm=re.search(r'<ul class="tnotes"[^>]*>(.*?)</ul>',s,re.S)
nb=s.count('<div class="brk">'); ns=nb+len(re.findall(r'<div class="story[ "]',s))
intro=bool(nm) and nb>1
DUR=14.5+(4.4 if m else 0)+(4.6 if nm else 0)+(2.6 if intro else 0)+(2.5 if '<details class="more"' in s else 1.5)
s=s.replace('</style>','.mwrap{overflow:hidden}\n.more{position:relative}.more summary{position:relative;overflow:visible}.more .mo{display:inline!important}.more .mc{display:none!important}.more.tapped .mo{display:none!important}.more.tapped .mc{display:inline!important}\n.tapr{position:absolute;left:50%;top:50%;width:70px;height:70px;border-radius:50%;border:4px solid #e5384f;opacity:0;pointer-events:none}\n.disc,.more summary{position:relative}.newb{position:absolute;right:-6px;top:-10px;font-family:MONO;font-size:11px;letter-spacing:1.5px;background:#e5384f;color:#fff;padding:3px 7px;border-radius:4px;opacity:0;box-shadow:0 2px 6px rgba(0,0,0,.25);z-index:5}.more summary .newb{right:-44px;top:-8px}\n#icard{position:absolute;left:30px;right:30px;top:290px;background:#141416;color:#fff;border-radius:22px;padding:26px 22px;opacity:0;text-align:center}\n#icard .ln{opacity:0}\n#icard .big{font-family:PF;font-weight:900;font-size:92px;line-height:.9;color:#ff5a70}\n#icard .bt{font-family:MONO;font-weight:700;font-size:19px;letter-spacing:4px;margin-top:6px}\n#icard .sm{font-family:PF;font-style:italic;font-weight:700;font-size:28px;margin-top:20px;line-height:1.15}\n#icard .sm b{color:#ffd166}\n</style>',1)
if intro:
    END=END.replace('<div id="endc">',f'<div id="icard"><div class="ln"><div class="big">{nb}</div><div class="bt">BREAKING STORIES</div></div><div class="ln"><div class="sm"><b>{ns} stories.</b> The biggest issue yet.</div></div></div>\n<div id="endc">',1)
if nm:
    lis=re.findall(r'<li(?: data-tag="([^"]*)")?>(.*?)</li>',nm.group(1),re.S)
    s=s.replace('</style>','#ncard{position:absolute;inset:0;background:#141416;color:#fff;display:flex;flex-direction:column;justify-content:center;padding:40px 30px;opacity:0}\n#ncard .lb{align-self:flex-start;font-family:MONO;font-weight:700;font-size:20px;letter-spacing:4px;color:#ff5a70;border:3px solid #ff5a70;padding:5px 12px;border-radius:4px}\n#ncard h4{font-family:PF;font-style:italic;font-weight:700;font-size:30px;margin:18px 0 6px;line-height:1.1}\n#ncard ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:14px}\n#ncard li{display:flex;gap:12px;align-items:flex-start;font-size:18px;font-weight:600;line-height:1.3;opacity:0}\n#ncard li b{flex:none;font-family:MONO;font-size:11.5px;letter-spacing:1.5px;background:#e5384f;color:#fff;padding:4px 7px;border-radius:4px;margin-top:2px}\n#ncard li b.th{background:#0f8b8d}#ncard li b.rc{background:#d4af37;color:#141416}\n</style>',1)
    items=''.join(f'<li><b class="{ {"THANKS":"th","RECORD":"rc"}.get(tag or "NEW","") }">{tag or "NEW"}</b><span>{txt}</span></li>' for tag,txt in lis)
    END=END.replace('<div id="endc">',f'<div id="ncard"><div class="lb">THIS ISSUE</div><h4>Issue No. {n}: what\'s new</h4><ul>{items}</ul></div>\n<div id="endc">',1)
if m:
    s=s.replace('</style>','#dcard{position:absolute;inset:0;background:#f2f3f5;display:flex;flex-direction:column;justify-content:center;padding:44px 34px;opacity:0}\n#dcard .lb{align-self:flex-start;font-family:MONO;font-weight:700;font-size:20px;letter-spacing:4px;color:#c8243b;border:3px solid #c8243b;padding:5px 12px;border-radius:4px;background:rgba(255,255,255,.6)}\n#dcard p{font-size:17px;line-height:1.45;color:#33353c;margin:22px 0 0}\n#dcard strong{color:#111216}\n</style>',1)
    END=END.replace('<div id="endc">','<div id="dcard"><div class="lb">DISCLAIMER</div><p>'+m.group(1)+'</p></div>\n<div id="endc">',1)
i=s.rfind('</div></body></html>')
s=s[:i]+END
tmp=tempfile.mkdtemp(); html=os.path.join(ROOT,'src',f'.trailer{n}.html')
open(html,'w').write(s)
js=os.path.join(tmp,'t.js'); frames=os.path.join(tmp,'f'); os.makedirs(frames)
open(js,'w').write(f"""const {{chromium}}=require('playwright');
(async()=>{{const b=await chromium.launch();
const p=await b.newPage({{viewport:{{width:480,height:853}},deviceScaleFactor:2.25}});
await p.goto('file://{html}');await p.waitForTimeout(600);
for(let i=0;i<{int(DUR*30)};i++){{await p.evaluate(t=>setT(t),i/30);
await p.screenshot({{path:`{frames}/f${{String(i).padStart(4,'0')}}.jpg`,type:'jpeg',quality:92}});}}
await b.close();}})();""")
subprocess.run(['node',js],check=True,cwd='/tmp')
subprocess.run(['ffmpeg','-y','-loglevel','error','-framerate','30','-i',f'{frames}/f%04d.jpg','-vf','scale=1080:1920:flags=lanczos,format=yuv420p','-c:v','libx264','-preset','veryfast','-crf','20','-movflags','+faststart',out],check=True)
if PROMO:
    # the "new on the site" tour plays first, then the issue trailer runs in full
    spl=os.path.join(tmp,'spliced.mp4')
    fc=('[0:v]fps=30,scale=1080:1920:flags=lanczos,format=yuv420p,setsar=1,setpts=PTS-STARTPTS[p];'
        '[1:v]fps=30,format=yuv420p,setsar=1,setpts=PTS-STARTPTS[t];[p][t]concat=n=2:v=1:a=0[v]')
    subprocess.run(['ffmpeg','-y','-loglevel','error','-i',PROMO,'-i',out,'-filter_complex',fc,'-map','[v]',
                    '-c:v','libx264','-preset','veryfast','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',spl],check=True)
    shutil.move(spl,out); print('promo plays first')
os.remove(html); shutil.rmtree(tmp); print('ok',out)
